DECLARE
  main_branch_id BIGINT;
BEGIN
  SELECT id INTO main_branch_id FROM public.branches WHERE code = 'MAIN' ORDER BY id LIMIT 1;
  IF main_branch_id IS NULL THEN RAISE EXCEPTION 'Cannot restore opening stock: MAIN branch does not exist'; END IF;

  CREATE TEMP TABLE tmp_opening_stock(name TEXT NOT NULL, selling_price NUMERIC(14,2) NOT NULL, opening_stock NUMERIC(14,3) NOT NULL) ON COMMIT DROP;
