 Single 4.0mm Black Roll',12000,0),('ASL Single 4.0mm Green Roll',12000,0),('ASL Single 4.0mm Red/m',150,88),('ASL Single 4.0mm Black/m',150,89),('ASL Single 4.0mm Green/m',150,89),('Matstar Twin/Earth 1.5mm Roll',2800,0),('Matstar Twin/Earth 1.5mm/m',50,90),('Evincable Twin/Earth 1.5mm Roll',7500,0),('Evincable Twin/Earth 1.5mm/m',90,90),('Evincable Twin/Earth 2.5mm Roll',10500,0),('Evincable Twin/Earth 2.5mm/m',130,74),('Flex Cable/m',50,90),('Single Switch Box',20,97),('Twin Switch Box',40,47),('Single Patrice',20,67),('Twin Patrice',40,18),('Circular box 4 way',20,50),('Circular box 3 way',20,49),('Saddle clips 20mm',15,478),('Conduit pipe 20mm Belma',100,23),('Conduit pipe 25mm Belma',200,10),('Conduit pipe 20mm Metro',180,20),('Conduit pipe 25mm Metro',260,10),('Mini trunking',100,34),('2by1 trunking',200,0),('Bends 20mm',20,80),('Bends 25mm',30,100),('Bends 32mm',40,100),('Couplers 20mm',10,175),('Couplers 25mm',15,100),('Couplers 32mm',30,100),('Din Rail',150,9),('Earth Rod Small',130,5),('Earth Rod Medium',260,3),('Earth Rod Big',390,4),('Electric Wire Box 4way',1500,9),('Electric Wire Box 5way',2000,40),('Electric Wire Box 6way',2500,2),('Electric Wire Box 8way',3100,70),('Electric Wire Box 12way',3500,17),('Mindy 40mm',550,2),('Mindy 50mm',700,1),('Mindy 60mm',850,1),('Stellar 60mm',500,2),('Stellar 70mm',550,2),('Stellar 80mm',600,1),('Tricycle 262',220,2),('Tricycle 263',300,2),('Tricycle 264',400,2),('Tricycle 265',650,2),('Tricycle 266',1050,1),('Tricycle No: 2  262',70,2),('Tricycle No: 2   263',100,1),('Tricycle No: 2   264',120,2),('Tricycle No: 2    265',150,2),('Tricycle No: 2    266',200,2),('Yongli Padlock 362',80,1),('Yongli Padlock 363',100,2),('Yongli Padlock 364',120,2),('Yongli Padlock 365',150,2),('Yongli Padlock 366',200,2),('7W DownLigther Warm White',260,5),('7W DownLigther Wh + Pink',300,10),('7W DownLigther Wh + Green',300,10),('7W DownLighter Wh + Red',300,10),('3W R.Recess Panel',200,5),('3 + 3W R.Recess Panel Wh + Blu',350,5),('6 + 3 Recess  Wh + Blue/Green',550,5),('6W R.Recess Panel (Wh)',300,5),('6w R.Surface Panel (Wh)',350,5),('12W R.Recess Panel (Wh)',350,5),('12W R.Surface Panel(Wh)',400,5),('Meter Box Metallic Small',300,2),('Meter Box Metallic Big',400,3),('Meter Box Metallic Small',1500,1),('Meter Box Coated Medium',1800,1),('Hammers',500,4);

  -- The workbook has 253 positive-stock rows. Match by name + selling price,
  -- which is unique in the source data even where names repeat.
  WITH expected AS (SELECT name,selling_price,MAX(opening_stock) AS opening_stock FROM tmp_opening_stock WHERE opening_stock>0 GROUP BY name,selling_price),
  matched AS (SELECT e.name,e.selling_price,e.opening_stock,p.id FROM expected e JOIN public.inventory_products_v2 p ON lower(trim(p.name))=lower(trim(e.name)) AND p.selling_price=e.selling_price AND p.is_active=TRUE),
  counts AS (SELECT (SELECT COUNT(*) FROM expected) expected_count,(SELECT COUNT(*) FROM matched) matched_count)
  SELECT CASE WHEN matched_count<>expected_count THEN pg_raise_exception('Opening stock restoration matched %s of %s positive workbook rows',matched_count,expected_count) END FROM counts;

  INSERT INTO public.inventory_stock_v2(product_id,branch_id,quantity_on_hand,updated_at)
  SELECT p.id,main_branch_id,e.opening_stock,NOW()
  FROM tmp_opening_stock e JOIN public.inventory_products_v2 p ON lower(trim(p.name))=lower(trim(e.name)) AND p.selling_price=e.selling_price AND p.is_active=TRUE
  WHERE e.opening_stock>0
  ON CONFLICT(product_id,branch_id) DO UPDATE SET quantity_on_hand=GREATEST(inventory_stock_v2.quantity_on_hand,EXCLUDED.quantity_on_hand),updated_at=NOW();

  INSERT INTO public.inventory_movements_v2(product_id,branch_id,movement_type,quantity_delta,reason)
  SELECT p.id,main_branch_id,'opening_balance',MAX(e.opening_stock),'Opening stock restoration from verified workbook'
  FROM tmp_opening_stock e JOIN public.inventory_products_v2 p ON lower(trim(p.name))=lower(trim(e.name)) AND p.selling_price=e.selling_price AND p.is_active=TRUE
  WHERE e.opening_stock>0 GROUP BY p.id;
END $$;

COMMIT;
